@Component
@Scope("prototype")
class Task { }

@Service
class Scheduler {
    @Autowired
    Task task; // Scheduler is a default singleton bean
}

@Component
class Startup {
    @PostConstruct
    void init() {
        throw new IllegalStateException("config missing");
    }
}

@Value("${feature.limit}")
private int limit;
// application.properties has no "feature.limit" key, and there's no default

@Service
class Counter {
    private int count = 0; // singleton bean, mutable instance field
    public int incrementAndGet() { return ++count; }
}
// Two concurrent HTTP requests both call counter.incrementAndGet()

@Service
class A {
    @Autowired
    private B b; // field injection, circular with B
}
@Service
class B {
    @Autowired
    private A a; // field injection, circular with A
}

@Configuration
class AppConfig {
    @Bean
    Engine engine() { return new Engine(); }

    @Bean
    Car car() {
        return new Car(engine());
    }

    @Bean
    Truck truck() {
        return new Truck(engine());
    }
}

interface PaymentGateway { void charge(); }

@Service
class CheckoutService {
    @Autowired
    PaymentGateway gateway; // no class anywhere implements PaymentGateway or is registered as one
}
